        // We do this by traversing the reverse graph starting from all "use" nodes.
        boolean[] canReachUse = new boolean[n + 1];
        Queue<Integer> queue = new ArrayDeque<>();
        for (int i = 1; i <= n; i++) {
            if (f[i] == 2) {
                canReachUse[i] = true;
                queue.add(i);
            }
        }

        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int v : radj[u]) {
                if (!canReachUse[v]) {
                    canReachUse[v] = true;
                    queue.add(v);
                }
            }
        }

