        // Step 1: Find all nodes that can reach a "use" node (f[i] == 2)
        // We do this by BFS/DFS on the reversed graph starting from all use nodes.
        boolean[] canReachUse = new boolean[n];
        Queue<Integer> queue = new LinkedList<>();
        for (int i = 0; i < n; i++) {
            if (f[i] == 2) {
                canReachUse[i] = true;
                queue.add(i);
            }
        }

        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int v : radj[u]) {
                if (!canReachUse[v]) {
                    canReachUse[v] = true;
                    queue.add(v);
                }
            }
        }

        // Step 2: Find all nodes that can be reached from an "assign" node (f[i] == 1)
        // such that the path does not pass through any other "assign" node.
        // We do this by BFS/DFS on the original graph starting from all assign nodes.
        // We only traverse to neighbors that are not assign nodes (to ensure no intermediate assign).
        boolean[] reachableFromAssign = new boolean[n];
        queue = new LinkedList<>();
        for (int i = 0; i < n; i++) {
            if (f[i] == 1) {
                reachableFromAssign[i] = true;
                queue.add(i);
            }
        }

        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int v : adj[u]) {
                // If v is an assign node, we don't traverse further from it in this BFS
                // because the path would have an intermediate assign node if we went through it.
                // However, v itself is an assign node, so it's a start point for another potential path.
                // But for the current path starting from u, we cannot pass through v if v is assign.
                // So we only add v to the queue if it's not an assign node.
                if (f[v] != 1) {
                    if (!reachableFromAssign[v]) {
