                        queue.add(v);
                    }
                }
            }
        }

        // Step 3: A node is interesting if it can reach a use node AND is reachable from an assign node
        // (via a path with no intermediate assigns).
        int[] result = new int[n];
        for (int i = 0; i < n; i++) {
            if (canReachUse[i] && reachableFromAssign[i]) {
                result[i] = 1;
            } else {
                result[i] = 0;
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (i > 0) sb.append("\n");
            sb.append(result[i]);
        }
        System.out.println(sb.toString());
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        public int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
