            for (int v : adj[i]) {
                revAdj[v].add(i);
            }
        }

        Queue<Integer> queue = new LinkedList<>();
        for (int i = 0; i < n; i++) {
            if (f[i] == 2) {
                canReachUse[i] = true;
                queue.offer(i);
            }
        }

        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int v : revAdj[u]) {
                if (!canReachUse[v]) {
                    canReachUse[v] = true;
                    queue.offer(v);
                }
            }
        }

        boolean[] canReachAssignClean = new boolean[n];
        queue = new LinkedList<>();
        for (int i = 0; i < n; i++) {
            if (f[i] == 1) {
                canReachAssignClean[i] = true;
                queue.offer(i);
            }
        }

        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int v : adj[u]) {
                // If v is an assignment node, we cannot go through it (unless it's the start, but we already started from all assignment nodes)
                // So if f[v] == 1, we skip it.
                if (f[v] == 1) {
                    continue;
                }
                if (!canReachAssignClean[v]) {
                    canReachAssignClean[v] = true;
                    queue.offer(v);
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (canReachUse[i] && canReachAssignClean[i]) {
                sb.append(1);
            } else {
                sb.append(0);
            }
            if (i < n - 1) {
                sb.append("\n");
            }
        }

        System.out.println(sb.toString());
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
