        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) {
            f[i] = Integer.parseInt(st.nextToken());
        }

        List<Integer>[] graph = new ArrayList[n];
        List<Integer>[] revGraph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
            revGraph[i] = new ArrayList<>();
        }

        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(st.nextToken()) - 1;
            int b = Integer.parseInt(st.nextToken()) - 1;
            graph[a].add(b);
            revGraph[b].add(a);
        }

        // Step 1: Find nodes that can reach a "use" node (f[i] == 2)
        // We do this by traversing the reverse graph starting from all "use" nodes.
        boolean[] canReachUse = new boolean[n];
        Queue<Integer> queue = new LinkedList<>();
        for (int i = 0; i < n; i++) {
            if (f[i] == 2) {
                canReachUse[i] = true;
                queue.add(i);
            }
        }

        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int v : revGraph[u]) {
                if (!canReachUse[v]) {
                    canReachUse[v] = true;
                    queue.add(v);
                }
            }
        }

        // Step 2: Find nodes that are reachable from an "assign" node (f[i] == 1)
        // AND can reach a "use" node.
        // We traverse the original graph starting from all "assign" nodes.
        // We only visit nodes that satisfy canReachUse[v].
        boolean[] interesting = new boolean[n];
        queue.clear();
        for (int i = 0; i < n; i++) {
            if (f[i] == 1 && canReachUse[i]) {
                interesting[i] = true;
                queue.add(i);
            }
        }

        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int v : graph[u]) {
                if (canReachUse[v] && !interesting[v]) {
                    interesting[v] = true;
                    queue.add(v);
                }
            }
        }

        // Step 3: Output the result
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (i > 0) sb.append("\n");
            sb.append(interesting[i] ? 1 : 0);
        }
        System.out.println(sb.toString());
    }
