                    fromAssignment[v] = true;
                    if (f[v] != 1) {
                        queue.add(v);
                    }
                }
            }
        }

        // Step 3: Output
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (i > 0) sb.append("\n");
            sb.append((canReachUse[i] && fromAssignment[i]) ? 1 : 0);
        }
        System.out.println(sb.toString());
    }
}
